1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Step of {@code POST /api/owners}: assigns the new owner's {@code membershipLevel} — a
10	 * number from 1 to 4. It starts at 1, gains a level when the owner has an email on file,
11	 * another when the owner has no namesakes ({@code namesakeCount} is 0), and the top level
12	 * when the owner's {@link Tenure tenure} exceeds {@link #TENURE_LEVEL_DAYS} days. A newly
13	 * created owner has zero tenure, so it never reaches level 4. It runs after
14	 * {@link CountNamesakes} so the namesake count is known, and after
15	 * {@link ResolveOwnerRegistrationDate} so the registration date is resolved, and before
16	 * {@link SaveOwner} persists the owner and {@link AuditOwnerCreated} records the level. The
17	 * value is stored with the row and returned unchanged on later reads.
18	 */
19	public class AssignMembershipLevel {
20	
21	    /** Tenure, in days, that an owner must exceed to reach the top membership level (4). */
22	    private static final long TENURE_LEVEL_DAYS = 365;
23	
24	    public void service(@Val Owner owner) {
25	        int level = 1;
26	        String email = owner.getEmail();
27	        if (email != null && !email.isBlank()) {
28	            level++;
29	        }
30	        Integer namesakeCount = owner.getNamesakeCount();
31	        if (namesakeCount != null && namesakeCount == 0) {
32	            level++;
33	        }
34	        if (Tenure.days(owner.getRegistrationDate(), LocalDate.now()) > TENURE_LEVEL_DAYS) {
35	            level++;
36	        }
37	        owner.setMembershipLevel(level);
38	    }
39	}
