1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners}: records the new owner's {@code namesakeCount} — the
9	 * number of existing owners that already share the same first and last name (compared
10	 * case-insensitively, see {@link Namesake}). It runs on the built owner before
11	 * {@link SaveOwner} persists it, so the new owner is not yet counted among its own
12	 * namesakes. The value is stored with the row and returned unchanged on later reads.
13	 */
14	public class CountNamesakes {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        int count = 0;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (Namesake.matches(existing, owner.getFirstName(), owner.getLastName())) {
20	                count++;
21	            }
22	        }
23	        owner.setNamesakeCount(count);
24	    }
25	}
