1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	/**
7	 * The single definition of an owner's "tenure": the number of whole days that have elapsed
8	 * since the owner's registration date. A newly registered owner — one registered as of the
9	 * reference date — has zero tenure. Provides the measure {@link AssignMembershipLevel} uses to
10	 * gate the top membership level, which is reserved for long-standing owners.
11	 */
12	final class Tenure {
13	
14	    private Tenure() {
15	    }
16	
17	    /** Whole days between {@code registrationDate} and {@code asOf}; zero when the date is
18	     *  unset or still in the future. */
19	    static long days(LocalDate registrationDate, LocalDate asOf) {
20	        if (registrationDate == null) {
21	            return 0;
22	        }
23	        return Math.max(ChronoUnit.DAYS.between(registrationDate, asOf), 0);
24	    }
25	}
