3	import java.util.Locale;
4	
5	/**
6	 * The single definition of an owner "household": owners sharing the same last name and
7	 * postcode. The last name is compared case-insensitively with runs of whitespace collapsed
8	 * to a single space; the postcode is taken as stored. Provides the deterministic identifier
9	 * shared by the household.
10	 *
11	 * <p>The identifier is derived deterministically from the normalized last name and postcode
12	 * — the first 12 upper-case hex characters of SHA-256 over {@code normalizedLastName + '|' +
13	 * postcode} — so every owner with the same last name and postcode resolves to the same value
14	 * regardless of creation order, and no owner-to-owner linking is needed.
15	 *
16	 * @see AssignHousehold stamps each owner with its computed identifier.
17	 * @see EnsureUniqueIdentity blocks a second owner in the same household unless it opts in.
18	 */
19	final class Household {
20	
21	    /** Length of the household identifier, in hex characters. */
22	    private static final int ID_LENGTH = 12;
23	
24	    private Household() {
25	    }
26	
27	    /** The stable identifier shared by every owner in the household keyed by {@code lastName}
28	     *  and {@code postcode}. */
29	    static String id(String lastName, String postcode) {
30	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
31	        return Sha256.hex(key, ID_LENGTH);
32	    }
33	
34	    /** A last name trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
35	    private static String normalizeName(String value) {
36	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
37	    }
38	}
