22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public interface OwnerMapper {
27	
28	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
29	    @Mapping(target = "initials", expression = "java(initials(owner))")
30	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
36	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
37	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /** The owner's stored E.164 telephone formatted for humans; see {@link TelephoneDisplay}. */
41	    default String telephoneDisplay(Owner owner) {
42	        return TelephoneDisplay.of(owner.getTelephone());
43	    }
44	
45	    /** The owner's derived identity key: normalized telephone, email and household id joined. */
46	    default String identityKey(Owner owner) {
47	        return IdentityKey.of(owner);
48	    }
49	
50	    /** Whether the owner was flagged as a possible duplicate at registration, i.e. it carries
51	     *  the id of an existing owner it possibly duplicates. */
52	    default boolean possibleDuplicate(Owner owner) {
53	        return owner.getPossibleDuplicateOf() != null;
54	    }
55	
56	    /** Format an owner's name for display as 'LastName, FirstName'. */
57	    default String displayName(Owner owner) {
58	        return owner.getLastName() + ", " + owner.getFirstName();
59	    }
60	
61	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
62	    default String initials(Owner owner) {
63	        return initial(owner.getFirstName()) + initial(owner.getLastName());
64	    }
65	
66	    private String initial(String name) {
67	        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
68	    }
69	
70	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
71	     *  last two digits of the registration date's year (e.g. 'SPR-SMI-0007-M26'). Absent until both the
72	     *  customer code and registration date have been assigned. */
73	    default String membershipNumber(Owner owner) {
74	        String customerCode = owner.getCustomerCode();
75	        LocalDate registrationDate = owner.getRegistrationDate();
76	        if (customerCode == null || registrationDate == null) {
77	            return null;
78	        }
79	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
80	    }
81	
82	    /** The Luhn check digit (0-9) over the digits of the owner's customerCode; absent until the
83	     *  customer code has been assigned. */
84	    default Integer checkDigit(Owner owner) {
85	        String customerCode = owner.getCustomerCode();
86	        return customerCode == null ? null : Luhn.checkDigit(customerCode);
87	    }
88	
89	    /** The owner's region, read back from the region segment of its customerCode (the identity's
90	     *  {@code <REGION>-<HASH8>} form). Until the customer code has been assigned it falls back to
91	     *  deriving the region from the postcode range first (NSW 2000-2099, VIC 3000-3099,
92	     *  QLD 4000-4099), then the city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
93	     *  Brisbane-&gt;QLD), or 'UNKNOWN' otherwise. */
94	    default String locality(Owner owner) {
95	        String region = CustomerCode.region(owner.getCustomerCode());
96	        return region != null ? region : Locality.region(owner.getCity(), owner.getPostcode());
97	    }
98	
99	    /** The owner's preferred contact channel: 'EMAIL' when an email address is on file,
100	     *  otherwise 'PHONE'. */
101	    default String contactPreference(Owner owner) {
102	        String email = owner.getEmail();
103	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
104	    }
105	
106	    /** The owner's age band at its registration date, derived from its birth date: 'MINOR'
107	     *  (under 18), 'ADULT' (18-64) or 'SENIOR' (65+); absent until a birth date is on file. */
108	    default String ageBand(Owner owner) {
109	        return AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate());
110	    }
111	
112	    Owner toOwner(OwnerDto ownerDto);
113	
114	    @Mapping(target = "id", ignore = true)
115	    @Mapping(target = "pets", ignore = true)
116	    Owner toOwner(OwnerFieldsDto ownerDto);
117	
118	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
119	
120	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
121	
122	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
123	        OwnerPageDto ownerPageDto = new OwnerPageDto();
124	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
125	        ownerPageDto.setPage(ownerPage.getNumber());
126	        ownerPageDto.setSize(ownerPage.getSize());
127	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
128	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
129	        return ownerPageDto;
130	    }
131	}
