22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return; // declared household member bypasses the duplicate block
24	        }
25	        String householdId = owner.getHouseholdId();
26	        if (householdId == null) {
27	            return; // no postcode -> no household -> nothing to collide with
28	        }
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (householdId.equals(existing.getHouseholdId())) {
31	                throw new DuplicateIdentityException(householdId);
32	            }
